399→            scrollbarColor: '#2a2a2a transparent'
400→          }}
401→        >
402→          <div style={{ display: 'flex', flexDirection: 'column', gap: '64px' }}>
403→            {messages.map((message, index) => {
404→              const isHeroPrompt = index === 0 && message.type === 'bot' && isInitialState;
405→
406→              return (
407→                <div
408→                  key={index}
409→                  className={index > 0 ? 'chat-message-enter' : ''}
