  6→/**
  7→ * ChatProjectCard
  8→ * Mini project card for inline display in chat messages
  9→ * Shows thumbnail, title, client, and link to full project
 10→ */
 11→
 12→interface ChatProjectCardProps {
 13→  slug: string;
 14→}
 15→
 16→export function ChatProjectCard({ slug }: ChatProjectCardProps) {
 17→  const project = getProject(slug);
 18→
 19→  if (!project) {
 20→    return null;
 21→  }
 22→
 23→  return (
 24→    <Link
 25→      href={`/projects/${project.slug}`}
 26→      className="chat-project-card"
 27→      style={{
 28→        display: 'flex',
 29→        gap: '16px',
 30→        alignItems: 'center',
 31→        padding: '12px',
 32→        marginTop: '16px',
