124→/**
125→ * Parse message text and extract project slugs
126→ * Returns array of { type: 'text' | 'project', content: string }
127→ */
128→export function parseMessageWithProjects(text: string): Array<{ type: 'text' | 'project'; content: string }> {
129→  const parts: Array<{ type: 'text' | 'project'; content: string }> = [];
130→  const projectRegex = /\[PROJECT:([a-z0-9-]+)\]/gi;
131→
132→  let lastIndex = 0;
133→  let match;
134→
135→  while ((match = projectRegex.exec(text)) !== null) {
136→    // Add text before the match
137→    if (match.index > lastIndex) {
138→      parts.push({
139→        type: 'text',
140→        content: text.slice(lastIndex, match.index)
141→      });
142→    }
143→
144→    // Add the project reference
145→    parts.push({
146→      type: 'project',
147→      content: match[1] // The slug
148→    });
149→
150→    lastIndex = match.index + match[0].length;
151→  }
152→
153→  // Add remaining text
154→  if (lastIndex < text.length) {
155→    parts.push({
156→      type: 'text',
157→      content: text.slice(lastIndex)
158→    });
159→  }
160→
161→  return parts.length > 0 ? parts : [{ type: 'text', content: text }];
162→}
